using System;using System.IO;using System.Linq;using System.Text;using System.Numerics;using System.Collections.Generic;using System.ComponentModel;using System.Runtime.Serialization;
namespace CircuitoStudio {
[DataContract]public enum FlowNeutralModel{[EnumMember] Unknown,[EnumMember] Explicit,[EnumMember] Ideal,[EnumMember] NoNeutralLoads}
[DataContract]public enum FlowConnection{[EnumMember] Unknown,[EnumMember] WyeNeutral,[EnumMember] Delta,[EnumMember] SingleLN,[EnumMember] SingleLL}
[DataContract]public enum FlowLoadModel{[EnumMember] ConstantPower,[EnumMember] ConstantImpedance}
[DataContract]public sealed class NetworkFlowSettings {
[DataMember,Browsable(false)]public string Engine{get;set;}[DataMember,DisplayName("Tensão nominal entre fases (V)")]public double NominalLineVoltageV{get;set;}[DataMember,DisplayName("Frequência dos dados (Hz)")]public double FrequencyHz{get;set;}[DataMember,DisplayName("Fator da tensão interna E")]public double SourceVoltageFactor{get;set;}[DataMember,DisplayName("R permanente da fonte por fase (Ω)")]public double? SourcePhaseROhm{get;set;}[DataMember,DisplayName("X permanente da fonte por fase (Ω)")]public double? SourcePhaseXOhm{get;set;}[DataMember,DisplayName("R do N/PEN da fonte (Ω)")]public double? SourceNeutralROhm{get;set;}[DataMember,DisplayName("X do N/PEN da fonte (Ω)")]public double? SourceNeutralXOhm{get;set;}[DataMember,DisplayName("Modelo de tensão do neutro")]public FlowNeutralModel NeutralModel{get;set;}[DataMember,DisplayName("Justificativa do neutro ideal")]public string IdealNeutralReference{get;set;}[DataMember,DisplayName("Autorizar R de fase por seção")]public bool AllowDerivedPhaseResistance{get;set;}[DataMember,DisplayName("Número máximo de iterações")]public int MaximumIterations{get;set;}[DataMember,DisplayName("Tolerância de tensão/KVL (V)")]public double VoltageToleranceV{get;set;}[DataMember,DisplayName("Tolerância de corrente (A)")]public double CurrentToleranceA{get;set;}[DataMember,DisplayName("Fator de relaxação")]public double Relaxation{get;set;}[DataMember,DisplayName("Piso de tensão de iteração (PU)")]public double MinimumLoadVoltagePu{get;set;}[DataMember,DisplayName("Referência dos dados/modelo")]public string Reference{get;set;}[DataMember,DisplayName("Versão dos dados")]public string DataVersion{get;set;}[DataMember,DisplayName("Condições / hipóteses")]public string Conditions{get;set;}
public NetworkFlowSettings(){Engine=NetworkFlow.EngineId;SourceVoltageFactor=1;MaximumIterations=500;VoltageToleranceV=CurrentToleranceA=1e-7;Relaxation=.5;MinimumLoadVoltagePu=.05;Reference=DataVersion=Conditions=IdealNeutralReference="";}public NetworkFlowSettings Copy(){return (NetworkFlowSettings)MemberwiseClone();}
public void Validate(){if(Engine!=NetworkFlow.EngineId||!Enum.IsDefined(typeof(FlowNeutralModel),NeutralModel))throw new InvalidDataException("Revisão/modelo de fluxo desconhecidos.");Project.Range(NominalLineVoltageV,1,1e6,"tensão nominal do fluxo");Project.Range(FrequencyHz,1,1000,"frequência do fluxo");Project.Range(SourceVoltageFactor,.5,1.5,"fator de tensão permanente");foreach(var v in new[]{SourcePhaseROhm,SourcePhaseXOhm,SourceNeutralROhm,SourceNeutralXOhm})if(v.HasValue)Project.Range(v.Value,0,1e12,"impedância permanente");Project.Range(MaximumIterations,1,10000,"iterações");Project.Range(VoltageToleranceV,1e-12,1,"tolerância V");Project.Range(CurrentToleranceA,1e-12,1,"tolerância A");Project.Range(Relaxation,.01,1,"relaxação");Project.Range(MinimumLoadVoltagePu,.001,.5,"tensão mínima de iteração");foreach(var s in new[]{Reference,DataVersion,Conditions,IdealNeutralReference})ReturnSizing.Text(s,false);}
}
[DataContract]public sealed class NetworkFlowLoad {
[DataMember,Browsable(false)]public string Engine{get;set;}[DataMember,DisplayName("Ligação física da carga")]public FlowConnection Connection{get;set;}[DataMember,DisplayName("Modelo de carga permanente")]public FlowLoadModel Model{get;set;}[DataMember,DisplayName("Segunda fase, somente ligação LL")]public FaultLive SecondPhase{get;set;}[DataMember,DisplayName("Referência dos dados/modelo")]public string Reference{get;set;}[DataMember,DisplayName("Condições / hipóteses")]public string Conditions{get;set;}
public NetworkFlowLoad(){Engine=NetworkFlow.EngineId;SecondPhase=FaultLive.L2;Reference=Conditions="";}public NetworkFlowLoad Copy(){return (NetworkFlowLoad)MemberwiseClone();}
public void Validate(){if(Engine!=NetworkFlow.EngineId||!Enum.IsDefined(typeof(FlowConnection),Connection)||!Enum.IsDefined(typeof(FlowLoadModel),Model)||!Enum.IsDefined(typeof(FaultLive),SecondPhase))throw new InvalidDataException("Revisão/ligação/modelo de carga desconhecidos.");ReturnSizing.Text(Reference,false);ReturnSizing.Text(Conditions,false);}
}
public sealed partial class Project{[DataMember(Order=120),Browsable(false)]public NetworkFlowSettings FlowSettings{get;set;}}
public sealed partial class Circuit{[DataMember(Order=120),Browsable(false)]public NetworkFlowLoad FlowLoad{get;set;}}
public sealed class FlowCircuitResult {
public Circuit Circuit;public Complex[] Current,EndVoltage;public double[] OperatingVoltagesV;public string VoltageMeaning;public double NominalLegVoltageV,MaximumAbsDropPercent,MinimumVoltagePu,MaximumVoltagePu;public Complex SendingVA,ReceivingVA,LossVA;
public double MaximumPhaseCurrentA{get{return Current.Take(3).Max(v=>Complex.Abs(v));}}public double NeutralCurrentA{get{return Complex.Abs(Current[3]);}}
}
public sealed class NetworkFlowResult {
public string Status,Detail;public bool Converged;public int Iterations;public double? MaximumVoltageErrorV,MaximumCurrentErrorA,KvlResidualV,PowerResidualVA;public Complex? SourceVA,LoadVA,LossVA;public List<FlowCircuitResult> Circuits=new List<FlowCircuitResult>();public FlowCircuitResult For(Circuit c){return Circuits.FirstOrDefault(row=>row.Circuit==c);}
}
public static class NetworkFlow {
public const string EngineId="cs-fluxo-quatro-fios-v1";
sealed class Input:Exception{public Input(string s):base(s){}}sealed class Iteration:Exception{public Iteration(string s):base(s){}}
sealed class Branch{public Circuit Circuit;public Board Board;public Branch Parent;public bool Feeder,NeedsNeutral;public List<Branch> Children=new List<Branch>();public Complex[] Voltage,Target,Current=new Complex[4],Z=new Complex[4];}
static void Need(bool value,string message){if(!value)throw new Input(message);}static bool Trace(string s){return !String.IsNullOrWhiteSpace(s)&&!s.TrimStart().StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase);}static Complex Z(double? r,double? x,string message){Need(r.HasValue&&x.HasValue,message);return new Complex(r.Value,x.Value);}static double Abs(Complex z){return Complex.Abs(z);}static double Square(Complex z){double a=Abs(z);return a*a;}static bool Finite(Complex z){return !double.IsNaN(z.Real)&&!double.IsNaN(z.Imaginary)&&!double.IsInfinity(z.Real)&&!double.IsInfinity(z.Imaginary);}
static int Phase(Circuit c){return c.PhaseLabel=="L1"?0:c.PhaseLabel=="L2"?1:c.PhaseLabel=="L3"?2:-1;}
static void ConfigureLoad(Project p,Branch b){var c=b.Circuit;var options=c.FlowLoad;Need(options!=null,"Defina ligação/modelo da carga "+c.Id);Need(Trace(options.Reference)&&Trace(options.Conditions),"Referência/condições da carga incompletas: "+c.Id);var w=c.Conductors;Need(w!=null,"Condutores tipados não definidos: "+c.Id);switch(options.Connection){case FlowConnection.WyeNeutral:Need(c.Phases==PhaseMode.Trifasico&&w.Connection==LiveConnection.ThreePhaseNeutral,"Carga estrela com N exige ligação3PN: "+c.Id);b.NeedsNeutral=true;break;case FlowConnection.Delta:Need(c.Phases==PhaseMode.Trifasico&&w.Connection==LiveConnection.ThreePhase,"Carga delta exige ligação3F sem N utilizado: "+c.Id);break;case FlowConnection.SingleLN:Need(c.Phases==PhaseMode.Monofasico&&w.Connection==LiveConnection.LineNeutral&&Phase(c)>=0,"Carga LN exige fase conhecida e ligação LN: "+c.Id);b.NeedsNeutral=true;break;case FlowConnection.SingleLL:Need(c.Phases==PhaseMode.Monofasico&&w.Connection==LiveConnection.LineLine&&Phase(c)>=0&&(int)options.SecondPhase<3&&(int)options.SecondPhase!=Phase(c),"Carga LL exige duas fases distintas declaradas: "+c.Id);break;default:throw new Input("Ligação da carga indefinida: "+c.Id);}double expected=options.Connection==FlowConnection.SingleLN?b.Board.Voltage/Math.Sqrt(3):b.Board.Voltage;Need(Math.Abs(c.Voltage-expected)<=.01*expected,"Tensão nominal não corresponde à ligação: "+c.Id);}
static void SetNeeds(Project p,Branch b){if(b.Feeder){Need(b.Circuit.Phases==PhaseMode.Trifasico&&Math.Abs(b.Circuit.Voltage-b.Board.Voltage)<.001,"Alimentador deve ser trifásico na tensão do quadro: "+b.Circuit.Id);Need(b.Circuit.Conductors!=null&&(b.Circuit.Conductors.Connection==LiveConnection.ThreePhase||b.Circuit.Conductors.Connection==LiveConnection.ThreePhaseNeutral),"Ligação trifásica do alimentador não declarada: "+b.Circuit.Id);Need(b.Circuit.FlowLoad==null,"Alimentador não recebe modelo de carga terminal: "+b.Circuit.Id);foreach(var child in b.Children)SetNeeds(p,child);b.NeedsNeutral=b.Children.Any(v=>v.NeedsNeutral);}else ConfigureLoad(p,b);if(b.NeedsNeutral){if(b.Feeder)Need(b.Circuit.Conductors!=null&&b.Circuit.Conductors.Connection==LiveConnection.ThreePhaseNeutral,"Alimentador com cargas N exige ligação3PN: "+b.Circuit.Id);Need(p.GroundingSource!=null&&p.GroundingSource.NeutralDistributed==true,"Neutro distribuído da fonte desconhecido/ausente.");Need(b.Circuit.Conductors!=null&&(b.Circuit.Conductors.HasNeutral==true||b.Circuit.Conductors.HasPEN==true),"N/PEN necessário no caminho: "+b.Circuit.Id);}}
static void SetImpedance(NetworkFlowSettings s,Branch b,StringBuilder log){var c=b.Circuit;string returnTrace="";Need(c.Cable.Parallel==1,"Divisão em paralelos não modelada: "+c.Id);Complex phase=0;if(c.LengthM>0){Need(Trace(c.Cable.Reference),"Referência de R/X da fase ausente: "+c.Id);double r=c.Cable.ResistanceOhmKm;if(r==0){Need(s.AllowDerivedPhaseResistance&&c.CableMm2>0,"R da fase desconhecida, sem derivação autorizada: "+c.Id);r=(c.Cable.Material==ConductorMaterial.Copper?23.7:37.6)/c.CableMm2;}phase=new Complex(r,c.Cable.ReactanceOhmKm)*c.LengthM/1000;}for(int i=0;i<3;i++)b.Z[i]=phase;
if(b.NeedsNeutral&&s.NeutralModel==FlowNeutralModel.Explicit&&c.LengthM>0){var w=c.Conductors;ReturnRole role=w.HasNeutral==true?ReturnRole.Neutral:ReturnRole.PEN;var selected=c.ReturnSizing;var rating=selected==null?null:role==ReturnRole.Neutral?selected.Neutral:selected.Protective;Need(rating!=null&&rating.Role==role,"R/X da seção N/PEN não selecionados: "+c.Id);Need(Trace(rating.Reference)&&Trace(rating.Source)&&Trace(rating.DataVersion)&&Trace(rating.Conditions),"Rastreabilidade do retorno incompleta: "+c.Id);b.Z[3]=Z(rating.ResistanceOhmKm,rating.ReactanceOhmKm,"R/X do retorno desconhecidos: "+c.Id)*c.LengthM/1000;returnTrace=" Retorno "+role+" / "+rating.SectionMm2+" mm²; referência "+rating.Reference+"; fonte "+rating.Source+"; versão "+rating.DataVersion+"; condições "+rating.Conditions+".";}else{b.Z[3]=0;returnTrace=!b.NeedsNeutral?" Subárvore sem cargas N: IN=0 pela ligação, não por equilíbrio presumido; ZN não requerido.":s.NeutralModel==FlowNeutralModel.Ideal?" Neutro ideal por hipótese: "+s.IdealNeutralReference:" Comprimento zero declarado no retorno.";}log.AppendLine(c.Id+": Zfase="+Format(phase)+" Ω; ZN/PEN usado="+Format(b.Z[3])+" Ω; retorno necessário="+b.NeedsNeutral+"; L="+c.LengthM+" m; referência "+c.Cable.Reference+"."+returnTrace);}
static Complex NominalPower(Circuit c){double p=c.PowerKw*c.DemandFactor;double q=(c.ReactiveKvarOverride.HasValue?c.ReactiveKvarOverride.Value:c.PowerKw*Math.Tan(Math.Acos(c.PowerFactor)))*c.DemandFactor;return new Complex(p,q)*1000;}
static Complex LoadCurrent(Complex s,Complex voltage,double nominal,FlowLoadModel model,NetworkFlowSettings settings,string id){if(s==Complex.Zero)return Complex.Zero;if(!Finite(voltage))throw new Iteration("Tensão não finita: "+id);if(Abs(voltage)<nominal*settings.MinimumLoadVoltagePu)throw new Iteration("Tensão de carga abaixo do piso do modelo: "+id);var current=model==FlowLoadModel.ConstantPower?Complex.Conjugate(s/voltage):Complex.Conjugate(s)/(nominal*nominal)*voltage;if(!Finite(current))throw new Iteration("Corrente não finita: "+id);return current;}
static Complex[] Terminal(Branch b,NetworkFlowSettings settings){var c=b.Circuit;var options=c.FlowLoad;var v=b.Voltage;var current=new Complex[4];var s=NominalPower(c);if(options.Connection==FlowConnection.WyeNeutral){double nominal=c.Voltage/Math.Sqrt(3);for(int i=0;i<3;i++)current[i]=LoadCurrent(s/3,v[i]-v[3],nominal,options.Model,settings,c.Id);current[3]=-current[0]-current[1]-current[2];}else if(options.Connection==FlowConnection.Delta){for(int i=0;i<3;i++){int other=(i+1)%3;var leg=LoadCurrent(s/3,v[i]-v[other],c.Voltage,options.Model,settings,c.Id);current[i]+=leg;current[other]-=leg;}}else{int first=Phase(c),second=options.Connection==FlowConnection.SingleLN?3:(int)options.SecondPhase;var leg=LoadCurrent(s,v[first]-v[second],c.Voltage,options.Model,settings,c.Id);current[first]+=leg;current[second]-=leg;}return current;}
static Complex[] Backward(Branch b,NetworkFlowSettings settings){var current=new Complex[4];if(b.Feeder){foreach(var child in b.Children){var next=Backward(child,settings);for(int k=0;k<4;k++)current[k]+=next[k];}}else current=Terminal(b,settings);b.Current=current;return current;}
static Complex[] Total(List<Branch> roots,NetworkFlowSettings settings){var total=new Complex[4];foreach(var root in roots){var next=Backward(root,settings);for(int i=0;i<4;i++)total[i]+=next[i];}return total;}
static void Forward(Branch b,Complex[] parent){b.Target=new Complex[4];for(int k=0;k<4;k++)b.Target[k]=parent[k]-b.Z[k]*b.Current[k];foreach(var child in b.Children)Forward(child,b.Target);}
static Complex Power(Complex[] v,Complex[] current){Complex s=0;for(int i=0;i<4;i++)s+=v[i]*Complex.Conjugate(current[i]);return s;}
static Complex Loss(Complex[] z,Complex[] current){Complex s=0;for(int k=0;k<4;k++)s+=z[k]*Square(current[k]);return s;}
static double[] Operating(Branch b,out string meaning,out double nominal){var c=b.Circuit;var v=b.Voltage;var connection=b.Feeder?(b.NeedsNeutral?FlowConnection.WyeNeutral:FlowConnection.Delta):c.FlowLoad.Connection;if(connection==FlowConnection.WyeNeutral){meaning="L1-N / L2-N / L3-N";nominal=c.Voltage/Math.Sqrt(3);return new[]{Abs(v[0]-v[3]),Abs(v[1]-v[3]),Abs(v[2]-v[3])};}if(connection==FlowConnection.Delta){meaning="L1-L2 / L2-L3 / L3-L1";nominal=c.Voltage;return new[]{Abs(v[0]-v[1]),Abs(v[1]-v[2]),Abs(v[2]-v[0])};}int first=Phase(c),second=connection==FlowConnection.SingleLN?3:(int)c.FlowLoad.SecondPhase;meaning=c.PhaseLabel+(second==3?"-N":"-L"+(second+1));nominal=c.Voltage;return new[]{Abs(v[first]-v[second])};}
public static NetworkFlowResult Run(Project p){p.Validate();var result=new NetworkFlowResult();var log=new StringBuilder();try{var s=p.FlowSettings;Need(s!=null,"Perfil de fluxo não informado.");Need(Trace(s.Reference)&&Trace(s.DataVersion)&&Trace(s.Conditions),"Fonte/versão/condições do equivalente permanente incompletas.");Need(s.NominalLineVoltageV==p.Source.LineVoltage&&s.FrequencyHz==p.Frequency,"Tensão/frequência do perfil não correspondem ao projeto.");Need(s.NeutralModel!=FlowNeutralModel.Unknown,"Escolha o modelo do neutro.");if(s.NeutralModel==FlowNeutralModel.Ideal)Need(Trace(s.IdealNeutralReference),"Neutro ideal exige hipótese/referência explícita.");Need(p.Boards.All(b=>Math.Abs(b.Voltage-s.NominalLineVoltageV)<.001),"Transformação entre quadros não modelada no fluxo.");var branches=new List<Branch>();var byBoard=new Dictionary<string,List<Branch>>();foreach(var board in p.Boards){var group=new List<Branch>();foreach(var c in board.Circuits){var b=new Branch{Circuit=c,Board=board,Feeder=c.ChildBoardId!=""};branches.Add(b);group.Add(b);}byBoard.Add(board.Id,group);}Need(branches.Count>0&&branches.Count<=10000,"Fluxo exige de1 a10000 circuitos.");foreach(var branch in branches)if(branch.Feeder){branch.Children=byBoard[branch.Circuit.ChildBoardId];foreach(var child in branch.Children)child.Parent=branch;}var roots=branches.Where(b=>b.Parent==null).ToList();foreach(var root in roots)SetNeeds(p,root);bool needsNeutral=roots.Any(b=>b.NeedsNeutral);Need(s.NeutralModel!=FlowNeutralModel.NoNeutralLoads||!needsNeutral,"Perfil sem cargas N é incompatível com ligação LN/estrelaN.");Complex zp=Z(s.SourcePhaseROhm,s.SourcePhaseXOhm,"R/X permanentes da fase da fonte desconhecidos.");Complex zn=needsNeutral&&s.NeutralModel==FlowNeutralModel.Explicit?Z(s.SourceNeutralROhm,s.SourceNeutralXOhm,"R/X do neutro/PEN da fonte desconhecidos."):Complex.Zero;var sourceZ=new[]{zp,zp,zp,zn};double u0=s.NominalLineVoltageV/Math.Sqrt(3)*s.SourceVoltageFactor;var emf=new[]{Complex.FromPolarCoordinates(u0,0),Complex.FromPolarCoordinates(u0,-2*Math.PI/3),Complex.FromPolarCoordinates(u0,2*Math.PI/3),Complex.Zero};foreach(var b in branches){SetImpedance(s,b,log);b.Voltage=(Complex[])emf.Clone();}Complex[] rootVoltage=(Complex[])emf.Clone();
for(int iteration=1;iteration<=s.MaximumIterations;iteration++){result.Iterations=iteration;var total=Total(roots,s);var oldCurrent=branches.Select(b=>(Complex[])b.Current.Clone()).ToArray();var rootTarget=new Complex[4];for(int k=0;k<4;k++)rootTarget[k]=emf[k]-sourceZ[k]*total[k];foreach(var root in roots)Forward(root,rootTarget);double dv=0;for(int k=0;k<4;k++){var next=rootVoltage[k]+s.Relaxation*(rootTarget[k]-rootVoltage[k]);dv=Math.Max(dv,Abs(next-rootVoltage[k]));rootVoltage[k]=next;}foreach(var b in branches)for(int k=0;k<4;k++){var next=b.Voltage[k]+s.Relaxation*(b.Target[k]-b.Voltage[k]);dv=Math.Max(dv,Abs(next-b.Voltage[k]));b.Voltage[k]=next;}var finalTotal=Total(roots,s);double di=0,kvl=0;for(int k=0;k<4;k++)kvl=Math.Max(kvl,Abs(rootVoltage[k]-emf[k]+sourceZ[k]*finalTotal[k]));for(int j=0;j<branches.Count;j++){var b=branches[j];var parent=b.Parent==null?rootVoltage:b.Parent.Voltage;for(int k=0;k<4;k++){di=Math.Max(di,Abs(b.Current[k]-oldCurrent[j][k]));kvl=Math.Max(kvl,Abs(b.Voltage[k]-parent[k]+b.Z[k]*b.Current[k]));}}result.MaximumVoltageErrorV=dv;result.MaximumCurrentErrorA=di;result.KvlResidualV=kvl;if(dv<=s.VoltageToleranceV&&di<=s.CurrentToleranceA&&kvl<=s.VoltageToleranceV){Complex load=0,loss=Loss(sourceZ,finalTotal);foreach(var b in branches){loss+=Loss(b.Z,b.Current);if(!b.Feeder)load+=Power(b.Voltage,b.Current);}Complex supply=Power(emf,finalTotal);double residual=Abs(supply-load-loss);result.PowerResidualVA=residual;if(residual>Math.Max(.001,1e-8*Math.Max(Abs(supply),Abs(load)+Abs(loss))))continue;result.Converged=true;result.Status="Convergido no modelo declarado";result.SourceVA=supply;result.LoadVA=load;result.LossVA=loss;foreach(var b in branches){string meaning;double nominal;var volts=Operating(b,out meaning,out nominal);var parent=b.Parent==null?rootVoltage:b.Parent.Voltage;result.Circuits.Add(new FlowCircuitResult{Circuit=b.Circuit,Current=(Complex[])b.Current.Clone(),EndVoltage=(Complex[])b.Voltage.Clone(),OperatingVoltagesV=volts,VoltageMeaning=meaning,NominalLegVoltageV=nominal,MaximumAbsDropPercent=volts.Max(v=>100*Math.Abs(nominal*s.SourceVoltageFactor-v)/nominal),MinimumVoltagePu=volts.Min()/nominal,MaximumVoltagePu=volts.Max()/nominal,SendingVA=Power(parent,b.Current),ReceivingVA=Power(b.Voltage,b.Current),LossVA=Loss(b.Z,b.Current)});}break;}}
if(!result.Converged){result.Status="Não convergiu; sem resultados aceitos";result.Detail="Limite de iterações atingido. Não publicar a última aproximação como solução.";}else result.Detail=Describe(p,result,log);return result;
}catch(Input error){result.Status="Dados incompletos/incompatíveis";result.Detail=error.Message;return result;}catch(Iteration error){result.Status="Não convergiu; sem resultados aceitos";result.Detail=error.Message;return result;}}
public static void AppendReport(Project p,Study study,StringBuilder text,IEnumerable<string> selected){var result=study.NetworkFlow;if(result==null)return;text.AppendLine("\r\nFLUXO POR FASE E NEUTRO — "+EngineId);text.AppendLine(result.Status);if(!result.Converged){text.AppendLine(result.Detail);return;}var settings=p.FlowSettings;text.AppendLine("Fonte permanente: "+settings.Reference+"; versão "+settings.DataVersion+"; condições "+settings.Conditions+"; N="+settings.NeutralModel+"; fatorE="+settings.SourceVoltageFactor+"; R/Xfase="+settings.SourcePhaseROhm+" / "+settings.SourcePhaseXOhm+" Ω; R/XN="+settings.SourceNeutralROhm+" / "+settings.SourceNeutralXOhm+" Ω. Hipótese ideal="+settings.IdealNeutralReference);text.AppendLine(result.Iterations+" iterações; resíduo KVL="+result.KvlResidualV+" V; resíduo potência="+result.PowerResidualVA+" VA; Sfonte="+Format(result.SourceVA.Value)+" VA; Scarga="+Format(result.LoadVA.Value)+" VA; perdas="+Format(result.LossVA.Value)+" VA. Totais da rede completa.");var ids=selected==null?null:new HashSet<string>(selected);foreach(var row in result.Circuits){if(ids!=null&&!ids.Contains(row.Circuit.Id))continue;var c=row.Circuit;text.AppendLine(c.Id+" — "+c.Name+"; "+(c.FlowLoad==null?"alimentador; potências/FD próprios não somados":c.FlowLoad.Connection+" / "+c.FlowLoad.Model+"; referência "+c.FlowLoad.Reference+"; condições "+c.FlowLoad.Conditions));text.AppendLine("I fundamental L1/L2/L3/N="+String.Join(" / ",row.Current.Select(i=>Format(i)+" A"))+". N orientado origem→carga, retorno geralmente negativo.");text.AppendLine("Tensões de operação ("+row.VoltageMeaning+")="+String.Join(" / ",row.OperatingVoltagesV.Select(v=>v.ToString("G10",System.Globalization.CultureInfo.InvariantCulture)+" V"))+"; PU mínimo/máximo="+row.MinimumVoltagePu+" / "+row.MaximumVoltagePu+"; |diferença de magnitudes E/recebida| máxima="+row.MaximumAbsDropPercent+"% em base nominal.");text.AppendLine("Senvio="+Format(row.SendingVA)+" VA; Srecebida="+Format(row.ReceivingVA)+" VA; perdas locais="+Format(row.LossVA)+" VA.");}text.AppendLine("Fonte/impedâncias diagonais e cargas declaradas, sem harmônicas/PWM/controle de fonte/dinâmica/malhas/paralelos. N fundamental não é N RMS total; não preenche dimensionamento automaticamente. Fases auxiliares não utilizadas em circuito monofásico não são apresentadas como condutores reais. Sem convergência não há resultados aceitos; limites/capacidade/conformidade exigem verificações próprias.");}
static string Csv(string value,bool user){value=value??"";if(user){string trimmed=value.TrimStart();if(trimmed.Length>0&&"=+-@".IndexOf(trimmed[0])>=0)value="'"+value;}return "\""+value.Replace("\"","\"\"")+"\"";}
public static void Export(Project p,string file){var result=Run(p);if(!result.Converged)throw new InvalidDataException("Sem solução validada; arquivo anterior preservado. "+result.Detail);var text=new StringBuilder("Circuit;I1FundA;I2FundA;I3FundA;NeutralFundA;VoltageMeaning;Operating1V;Operating2V;Operating3V;MinimumPu;MaximumPu;DropAbsPercent;SendingKw;SendingKvar;ReceivingKw;ReceivingKvar;LossKw;LossKvar;Engine;Reference\r\n");Func<double,string> number=x=>Csv(x.ToString("R",System.Globalization.CultureInfo.InvariantCulture),false);foreach(var row in result.Circuits){var values=new List<string>{Csv(row.Circuit.Id,true)};values.AddRange(row.Current.Select(i=>number(Abs(i))));values.Add(Csv(row.VoltageMeaning,true));for(int i=0;i<3;i++)values.Add(i<row.OperatingVoltagesV.Length?number(row.OperatingVoltagesV[i]):"\"\"");values.AddRange(new[]{row.MinimumVoltagePu,row.MaximumVoltagePu,row.MaximumAbsDropPercent,row.SendingVA.Real/1000,row.SendingVA.Imaginary/1000,row.ReceivingVA.Real/1000,row.ReceivingVA.Imaginary/1000,row.LossVA.Real/1000,row.LossVA.Imaginary/1000}.Select(number));values.Add(Csv(EngineId,true));values.Add(Csv(p.FlowSettings.Reference,true));text.AppendLine(String.Join(";",values));}if(Encoding.UTF8.GetByteCount(text.ToString())>32*1024*1024)throw new InvalidDataException("CSV de fluxo excede32MiB; arquivo anterior preservado.");string full=Path.GetFullPath(file),temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,text.ToString(),new UTF8Encoding(true));if(File.Exists(full))File.Replace(temp,full,full+".bak");else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}
static string Format(Complex z){return z.Real.ToString("G10",System.Globalization.CultureInfo.InvariantCulture)+" +j("+z.Imaginary.ToString("G10",System.Globalization.CultureInfo.InvariantCulture)+")";}
static string Describe(Project p,NetworkFlowResult result,StringBuilder log){var s=p.FlowSettings;return EngineId+"; fonte permanente "+s.Reference+"; versão "+s.DataVersion+"; condições "+s.Conditions+"; fatorE="+s.SourceVoltageFactor+"; neutro="+s.NeutralModel+"; justificativa ideal="+s.IdealNeutralReference+".\r\n"+result.Iterations+" iterações; ΔV="+result.MaximumVoltageErrorV+" V; ΔI="+result.MaximumCurrentErrorA+" A; resíduo KVL="+result.KvlResidualV+" V; resíduo potência="+result.PowerResidualVA+" VA.\r\nSfonte="+Format(result.SourceVA.Value)+" VA; Scargas="+Format(result.LoadVA.Value)+" VA; perdas="+Format(result.LossVA.Value)+" VA.\r\n"+log+"Varredura backward/forward por quatro potenciais, fonte única comum às raízes e impedâncias diagonais. P/Q e demanda aplicados uma vez por carga terminal; alimentador não soma sua potência/FD novamente. Correntes fundamentais senoidais, não RMS total de harmônicas; carga PQ ou impedância e ligação explicitamente declaradas. Não deduz retornoN de equilíbrio nem preenche IN,RMS de dimensionamento. Sem matriz de acoplamento mútuo, controle AVR/UPS, dinâmica de máquinas, harmônicas, redes malhadas, paralelos ou certificação normativa. Fonte de regime permanente é independente do equivalente de curto/Xd inicial. Tensões de fases não utilizadas em cargas monofásicas são variáveis auxiliares, sem declaração de condutor físico. Queda é referida à tensão interna E, em base nominal; PU mostra separadamente a tensão efetiva.";}
}
}
